package io.clipbridge.android;
import org.json.*;
import okhttp3.*;
import java.io.*;
import java.util.*;
final class GroupNetwork {
    private static final OkHttpClient HTTP=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).connectTimeout(10,java.util.concurrent.TimeUnit.SECONDS).readTimeout(30,java.util.concurrent.TimeUnit.SECONDS).callTimeout(30,java.util.concurrent.TimeUnit.SECONDS).build();
    private final String root,auth;private final Set<String> directories=new HashSet<>();
    GroupNetwork(String root,String username,String password,String token){this.root=root.replaceAll("/+$","")+"/";auth=username!=null?"Basic "+GroupCrypto.b64(GroupCrypto.bytes(username+":"+password)):token!=null?"Bearer "+token:"";}
    private JSONObject exchange(String method,String path,JSONObject body,String bearer,boolean create)throws Exception{RequestBody data=body==null?null:RequestBody.create(GroupCrypto.bytes(body.toString()),MediaType.parse("application/json"));Request.Builder builder=new Request.Builder().url(root+path).method(method,data).header("Cache-Control","no-cache, no-store");String authorization=bearer==null?auth:"Bearer "+bearer;if(!authorization.isEmpty())builder.header("Authorization",authorization);if(create)builder.header("If-None-Match","*");try(Response response=HTTP.newCall(builder.build()).execute()){
        if(method.equals("GET")&&response.code()==404)return null;if(method.equals("MKCOL")&&response.code()==405)return null;
        if(!response.isSuccessful())throw new HttpFailure(response.code());if(!method.equals("GET"))return new JSONObject();if(response.body()==null)throw new IOException();try(InputStream input=response.body().byteStream();ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(output.size()+n>250000)throw new IOException("同步组数据过大");output.write(buffer,0,n);}return new JSONObject(output.toString("UTF-8"));}}}
    static String message(Exception e,boolean dav){if(e instanceof IllegalArgumentException||e instanceof IllegalStateException)return e.getMessage()==null?"输入信息无效":e.getMessage();if(e instanceof SecurityException||e instanceof org.bouncycastle.crypto.CryptoException)return "设备验证失败，请重新生成邀请并核对安全码。";if(e instanceof HttpFailure){int code=((HttpFailure)e).code;if(code==401)return dav?"WebDAV 账号或应用密码不正确。":"服务器认证失败，请检查管理码或重新生成邀请。";if(code==403)return "服务器拒绝访问，请检查目录读写权限。";if(code==429)return "服务器请求过于频繁，请稍后重试或调大检查间隔。";if(code==404)return dav?"WebDAV 目录或邀请不存在，请检查地址。":"邀请不存在或已过期，请检查服务器地址与端口。";if(code==400)return dav?"WebDAV 拒绝目录或请求，请检查目录地址。":"服务器拒绝请求，请重新生成邀请。";}return "连接失败，请检查网络和服务器地址。";}
    static final class HttpFailure extends IOException {final int code;HttpFailure(int code){super("HTTP "+code);this.code=code;}}
    JSONObject get(String path)throws Exception{return exchange("GET",path,null,null,false);}
    void put(String path,JSONObject value,String token,boolean create)throws Exception{exchange("PUT",path,value,token,create);}
    void post(String path,JSONObject value,String token)throws Exception{exchange("POST",path,value,token,false);}
    void ensure(String path)throws Exception{String parent="";for(String part:path.split("/"))if(!part.isEmpty()){parent+=part+"/";if(directories.contains(parent))continue;try{exchange("MKCOL",parent,null,null,false);}catch(HttpFailure failure){Request request=new Request.Builder().url(root+parent).method("PROPFIND",null).header("Authorization",auth).header("Depth","0").build();try(Response response=HTTP.newCall(request).execute()){if(response.code()!=207)throw failure;}}directories.add(parent);}}
    static GroupNetwork store(JSONObject group)throws Exception{JSONObject c=group.getJSONObject("connection");if(c.optString("transport").equals("relay"))return new GroupNetwork(c.getString("server").replaceAll("/+$","")+"/v2/groups/"+group.getString("id")+"/store/","group",group.getString("access"),null);return new GroupNetwork(c.getString("server"),c.getString("username"),c.getString("password"),null);}
    static String prefix(JSONObject group)throws Exception{return group.getJSONObject("connection").optString("transport").equals("webdav")?GroupCrypto.storagePrefix(group):"";}
    static void provision(JSONObject group,String setup)throws Exception{JSONObject c=group.getJSONObject("connection");if(c.optString("transport").equals("webdav"))return;new GroupNetwork(c.getString("server"),null,null,null).post("v2/groups",new JSONObject().put("id",group.getString("id")).put("authHash",GroupCrypto.b64(java.security.MessageDigest.getInstance("SHA-256").digest(GroupCrypto.bytes(group.getString("access"))))),setup);}
    private static final Map<String,Long> published=new HashMap<>();
    static synchronized void publish(JSONObject group,JSONObject identity)throws Exception{String writer=group.getString("id")+":"+identity.getJSONObject("member").getString("id");long sequence=group.getLong("sequence");if(published.getOrDefault(writer,0L)>sequence)return;GroupNetwork store=store(group);String prefix=prefix(group),author=identity.getJSONObject("member").getString("id");store.ensure(prefix+"members/");JSONObject feed=GroupCrypto.feed(group,identity);store.put(prefix+"members/"+author+".json",GroupCrypto.seal(GroupCrypto.un64(group.getString("directoryKey")),"clipbridge:group-directory:1:"+group.getString("id")+":"+author,feed.toString()),null,false);published.put(writer,sequence);}
    static JSONObject read(JSONObject group,String author)throws Exception{Protocol.id(author);JSONObject box=store(group).get(prefix(group)+"members/"+author+".json");return box==null?null:new JSONObject(GroupCrypto.open(GroupCrypto.un64(group.getString("directoryKey")),"clipbridge:group-directory:1:"+group.getString("id")+":"+author,box));}
    static final class Rendezvous {
        final GroupNetwork network;final String prefix,token;
        Rendezvous(JSONObject connection,String locator,String token)throws Exception{GroupCrypto.connection(connection);if(!locator.matches("[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{6}"))throw new IllegalArgumentException();this.token=token;boolean relay=connection.optString("transport").equals("relay");prefix=relay?"":"clipbridge/invites/"+locator+"/";network=relay?new GroupNetwork(connection.getString("server").replaceAll("/+$","")+"/v2/invitations/"+locator+"/",null,null,null):new GroupNetwork(connection.getString("server"),connection.getString("username"),connection.getString("password"),null);}
        void create(JSONObject group,String locator,JSONObject meta)throws Exception{JSONObject c=group.getJSONObject("connection");if(c.optString("transport").equals("relay")){new GroupNetwork(c.getString("server"),null,null,null).post("v2/groups/"+group.getString("id")+"/invitations/"+locator,new JSONObject().put("meta",meta).put("ownerHash",GroupCrypto.b64(java.security.MessageDigest.getInstance("SHA-256").digest(GroupCrypto.bytes(token)))),group.getString("access"));}else{if(network.get(prefix+"meta.json")!=null)throw new IllegalStateException("邀请编号冲突，请重新生成");network.ensure(prefix);network.put(prefix+"meta.json",meta,null,true);}}
        JSONObject get(String slot)throws Exception{return network.get(prefix+slot+".json");}
        private boolean equal(Object a,Object b)throws Exception{if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(!GroupCrypto.keys(x).equals(GroupCrypto.keys(y)))return false;for(String key:GroupCrypto.keys(x))if(!equal(x.get(key),y.get(key)))return false;return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}return String.valueOf(a).equals(String.valueOf(b));}
        void put(String slot,JSONObject value)throws Exception{JSONObject observed=get(slot);if(observed!=null){if(!equal(observed,value))throw new SecurityException("配对消息冲突，请重新生成邀请");return;}try{network.put(prefix+slot+".json",value,prefix.isEmpty()?token:null,true);}catch(HttpFailure e){if(e.code!=409&&e.code!=412)throw e;JSONObject old=get(slot);if(old==null||!equal(old,value))throw new SecurityException("配对消息冲突，请重新生成邀请");}}
    }
    static String link(JSONObject connection,String code)throws Exception{return "clipbridge://group#"+Base64.getUrlEncoder().withoutPadding().encodeToString(GroupCrypto.bytes(new JSONObject().put("connection",connection).put("code",GroupPake.normalize(code)).toString()));}
    static JSONObject parse(String text)throws Exception{if(text.length()>8192||!text.startsWith("clipbridge://group#"))throw new IllegalArgumentException("无效的同步组邀请");JSONObject value=new JSONObject(new String(Base64.getUrlDecoder().decode(text.substring(text.indexOf('#')+1)),java.nio.charset.StandardCharsets.UTF_8));GroupCrypto.connection(value.getJSONObject("connection"));value.put("code",GroupPake.normalize(value.getString("code")));return value;}
}
